pub fn printHunkHeader(writer: anytype, config: DiffConfig, original_line_number: usize, original_line_count: usize, changed_line_number: usize, changed_line_count: usize) !void {
        if (config.enable_ansi_colors) {
            _ = try writer.print("{s}@@ -{},{} +{},{} @@{s}\n", .{ colors.yellow, original_line_number, original_line_count, changed_line_number, changed_line_count, colors.reset });
        } else {
            _ = try writer.print("@@ -{},{} +{},{} @@\n", .{ original_line_number, original_line_count, changed_line_number, changed_line_count });
        }
}

pub fn printDiff(allocator: std.mem.Allocator, writer: anytype, diff_segments: []const DiffSegment, config: DiffConfig) std.Io.Writer.Error!void {
        var removed_line_number: usize = 1;
        _ = &removed_line_number;
        var inserted_line_number: usize = 1;
        _ = &inserted_line_number;
        var removed_diff_lines: usize = 0;
        _ = &removed_diff_lines;
        var inserted_diff_lines: usize = 0;
        _ = &inserted_diff_lines;
        var has_skipped_segments = false;
        _ = &has_skipped_segments;
        for (cp_iter_slice(diff_segments)) |seg| {
            _ = &seg;
            if (seg.skip) {
                has_skipped_segments = true;
                break;
            }
        }
        var was_skipped = false;
        _ = &was_skipped;
        var seg_i: usize = 0;
        _ = &seg_i;
        for (cp_iter_slice(diff_segments)) |segment| {
            _ = &segment;
            defer {
            {
                removed_line_number = (removed_line_number + segment.removed_line_count);
                inserted_line_number = (inserted_line_number + segment.inserted_line_count);
                seg_i = (seg_i + 1);
            }
            }
            if (((was_skipped and (!segment.skip)) or ((has_skipped_segments and (seg_i == 0)) and (!segment.skip)))) {
                var original_line_count: usize = 0;
                _ = &original_line_count;
                var changed_line_count: usize = 0;
                _ = &changed_line_count;
                for (cp_iter_slice(diff_segments[seg_i..])) |seg| {
                    _ = &seg;
                    if (seg.skip) {
                        break;
                    }
                    original_line_count = (original_line_count + seg.removed_line_count);
                    changed_line_count = (changed_line_count + seg.inserted_line_count);
                }
                _ = try printHunkHeader(writer, config, removed_line_number, original_line_count, inserted_line_number, changed_line_count);
                was_skipped = false;
            }
            switch (segment.mode) {
.equal => {
if (segment.skip) {
                was_skipped = true;
                continue;
            }
            _ = try printLinePrefix(writer, config, prefix_styles.equal);
            _ = try printSegment(segment.removed, writer, config, styles.equal);
            _ = try writer.writeAll("\n");
},
.removed => {
_ = try printLinePrefix(writer, config, prefix_styles.removed);
            _ = try printSegment(segment.removed, writer, config, styles.removed_line);
            _ = try writer.writeAll("\n");
            removed_diff_lines = (removed_diff_lines + segment.removed_line_count);
},
.inserted => {
_ = try printLinePrefix(writer, config, prefix_styles.inserted);
            _ = try printSegment(segment.inserted, writer, config, styles.inserted_line);
            _ = try writer.writeAll("\n");
            inserted_diff_lines = (inserted_diff_lines + segment.inserted_line_count);
},
.modified => {
_ = try printModifiedSegment(segment, allocator, writer, config, ModifiedStyle{ .single_line = false });
            removed_diff_lines = (removed_diff_lines + segment.removed_line_count);
            inserted_diff_lines = (inserted_diff_lines + segment.inserted_line_count);
},
}
        }
        _ = try writer.writeAll("\n");
        _ = try printDiffFooter(writer, config, removed_diff_lines, inserted_diff_lines);
}
